);

CREATE TABLE `goods_receipt_items` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`goods_receipt_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`purchase_order_item_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`inventory_batch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`batch_number` varchar(100),
	`manufacturing_date` date,
	`expiration_date` date,
	`quantity_received` decimal(14,3) NOT NULL,
	`quantity_accepted` decimal(14,3) NOT NULL,
	`quantity_rejected` decimal(14,3) NOT NULL,
	`base_quantity` decimal(14,3) NOT NULL,
	`unit_cost` decimal(14,4) NOT NULL,
	`rejection_reason` varchar(500),
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `chk_receipt_items_quantities` CHECK(`goods_receipt_items`.`quantity_received` > 0 AND `goods_receipt_items`.`quantity_accepted` >= 0 AND `goods_receipt_items`.`quantity_rejected` >= 0 AND `goods_receipt_items`.`quantity_received` = `goods_receipt_items`.`quantity_accepted` + `goods_receipt_items`.`quantity_rejected`)
);

CREATE TABLE `goods_receipts` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`receipt_number` varchar(100) NOT NULL,
	`purchase_order_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`supplier_invoice_number` varchar(100) NOT NULL,
	`status` enum('DRAFT','POSTED') NOT NULL DEFAULT 'POSTED',
	`received_at` datetime NOT NULL,
	`received_by` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`notes` text,
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_goods_receipts_number` UNIQUE INDEX(`receipt_number`),
	CONSTRAINT `uq_goods_receipts_invoice` UNIQUE INDEX(`purchase_order_id`,`supplier_invoice_number`)
);

CREATE TABLE `inventories` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`quantity_on_hand` decimal(14,3) NOT NULL DEFAULT (0),
	`quantity_reserved` decimal(14,3) NOT NULL DEFAULT (0),
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_inventory_branch_product` UNIQUE INDEX(`branch_id`,`product_id`),
	CONSTRAINT `chk_inventory_quantities` CHECK(`inventories`.`quantity_on_hand` >= 0 AND `inventories`.`quantity_reserved` >= 0 AND `inventories`.`quantity_reserved` <= `inventories`.`quantity_on_hand`)
);

CREATE TABLE `inventory_adjustment_items` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`inventory_adjustment_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`inventory_batch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`quantity_before` decimal(14,3) NOT NULL,
	`counted_quantity` decimal(14,3) NOT NULL,
	`quantity_change` decimal(14,3) NOT NULL,
	`created_at` timestamp DEFAULT (now()),
	CONSTRAINT `chk_adjustment_items_qty` CHECK(`inventory_adjustment_items`.`quantity_before` >= 0 AND `inventory_adjustment_items`.`counted_quantity` >= 0 AND `inventory_adjustment_items`.`quantity_change` = `inventory_adjustment_items`.`counted_quantity` - `inventory_adjustment_items`.`quantity_before`)
);

CREATE TABLE `inventory_adjustments` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`adjustment_number` varchar(100) NOT NULL,
	`status` enum('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED','POSTED','CANCELLED') NOT NULL DEFAULT 'DRAFT',
	`reason` text NOT NULL,
	`created_by` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`approved_by` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`approved_at` datetime,
	`posted_at` datetime,
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_adjustments_number` UNIQUE INDEX(`adjustment_number`)
);

CREATE TABLE `inventory_batches` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`inventory_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`batch_number` varchar(100) NOT NULL,
	`expiration_date` date,
	`manufacturing_date` date,
	`quantity_received` decimal(14,3) NOT NULL,
	`quantity_available` decimal(14,3) NOT NULL,
	`unit_cost` decimal(14,4) NOT NULL,
	`received_at` datetime NOT NULL,
	`status` enum('ACTIVE','QUARANTINED','EXPIRED','DEPLETED','RECALLED') NOT NULL DEFAULT 'ACTIVE',
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `chk_batches_quantities` CHECK(`inventory_batches`.`quantity_received` >= 0 AND `inventory_batches`.`quantity_available` >= 0 AND `inventory_batches`.`quantity_available` <= `inventory_batches`.`quantity_received`),
	CONSTRAINT `chk_batches_cost` CHECK(`inventory_batches`.`unit_cost` >= 0),
	CONSTRAINT `chk_batches_dates` CHECK(`inventory_batches`.`manufacturing_date` IS NULL OR `inventory_batches`.`expiration_date` IS NULL OR `inventory_batches`.`manufacturing_date` <= `inventory_batches`.`expiration_date`)
);

CREATE TABLE `inventory_movements` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`inventory_batch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`movement_type` enum('PURCHASE_RECEIVED','SALE','SALE_RETURN','PURCHASE_RETURN','STOCK_ADJUSTMENT','STOCK_TRANSFER_IN','STOCK_TRANSFER_OUT','EXPIRED','DAMAGED','REVERSAL') NOT NULL,
	`reference_type` varchar(100),
	`reference_id` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`quantity_change` decimal(14,3) NOT NULL,
	`quantity_before` decimal(14,3) NOT NULL,
	`quantity_after` decimal(14,3) NOT NULL,
	`unit_cost` decimal(14,4) NOT NULL DEFAULT (0),
	`reason` text,
	`performed_by` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`created_at` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `chk_movements_balance` CHECK(`inventory_movements`.`quantity_before` >= 0 AND `inventory_movements`.`quantity_after` >= 0 AND `inventory_movements`.`quantity_change` = `inventory_movements`.`quantity_after` - `inventory_movements`.`quantity_before`)
);

CREATE TABLE `manufacturers` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
