);

CREATE TABLE `prescription_items` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`prescription_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`prescribed_quantity` decimal(14,3) NOT NULL,
	`total_dispensed_quantity` decimal(14,3) NOT NULL DEFAULT (0),
	`dosage_instructions` text NOT NULL,
	`frequency` varchar(150),
	`duration` varchar(150),
	`created_at` timestamp DEFAULT (now()),
	CONSTRAINT `chk_prescription_items_qty` CHECK(`prescription_items`.`prescribed_quantity` > 0 AND `prescription_items`.`total_dispensed_quantity` >= 0 AND `prescription_items`.`total_dispensed_quantity` <= `prescription_items`.`prescribed_quantity`)
