	`prescription_date` date NOT NULL,
	`valid_until` date,
	`image_path` varchar(500),
	`status` enum('PENDING_VERIFICATION','VERIFIED','PARTIALLY_DISPENSED','FULLY_DISPENSED','REJECTED','EXPIRED') NOT NULL DEFAULT 'PENDING_VERIFICATION',
	`verified_by` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`verified_at` datetime,
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `chk_prescriptions_dates` CHECK(`prescriptions`.`valid_until` IS NULL OR `prescriptions`.`valid_until` >= `prescriptions`.`prescription_date`)
);

CREATE TABLE `product_barcodes` (
