CREATE TABLE `product_units` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`product_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`unit_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`conversion_factor` decimal(14,3) NOT NULL,
	`is_base_unit` boolean NOT NULL DEFAULT false,
	`can_be_purchased` boolean NOT NULL DEFAULT true,
	`can_be_sold` boolean NOT NULL DEFAULT true,
	`is_active` boolean NOT NULL DEFAULT true,
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_product_unit` UNIQUE INDEX(`product_id`,`unit_id`),
