	`brand_name` varchar(255),
	`product_name` varchar(255) NOT NULL,
	`strength` varchar(100),
	`dosage_form` varchar(100),
	`description` text,
	`prescription_classification` enum('OTC','PRESCRIPTION','CONTROLLED','OTHER') NOT NULL DEFAULT 'OTC',
	`requires_prescription` boolean NOT NULL DEFAULT false,
	`reorder_level` decimal(14,3) NOT NULL DEFAULT (0),
	`is_active` boolean NOT NULL DEFAULT true,
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_products_sku` UNIQUE INDEX(`sku`),
	CONSTRAINT `chk_products_reorder` CHECK(`products`.`reorder_level` >= 0)
);

CREATE TABLE `purchase_order_items` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`purchase_order_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_unit_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`conversion_factor` decimal(14,3) NOT NULL,
	`quantity_ordered` decimal(14,3) NOT NULL,
	`quantity_received` decimal(14,3) NOT NULL DEFAULT (0),
	`unit_cost` decimal(14,4) NOT NULL,
	`line_total` decimal(14,2) NOT NULL,
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_po_items_unit` UNIQUE INDEX(`purchase_order_id`,`product_unit_id`),
	CONSTRAINT `chk_po_items_quantities` CHECK(`purchase_order_items`.`quantity_ordered` > 0 AND `purchase_order_items`.`quantity_received` >= 0 AND `purchase_order_items`.`quantity_received` <= `purchase_order_items`.`quantity_ordered`),
	CONSTRAINT `chk_po_items_cost` CHECK(`purchase_order_items`.`unit_cost` >= 0 AND `purchase_order_items`.`line_total` >= 0)
);

CREATE TABLE `purchase_orders` (
