	`sale_item_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`inventory_batch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`quantity` decimal(14,3) NOT NULL,
	`unit_cost` decimal(14,4) NOT NULL,
	`created_at` timestamp DEFAULT (now()),
	CONSTRAINT `chk_sale_item_batches_qty` CHECK(`sale_item_batches`.`quantity` > 0 AND `sale_item_batches`.`unit_cost` >= 0)
);

CREATE TABLE `sale_items` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`sale_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_unit_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_name_snapshot` varchar(255) NOT NULL,
	`generic_name_snapshot` varchar(255),
	`quantity` decimal(14,3) NOT NULL,
	`base_quantity` decimal(14,3) NOT NULL,
	`unit_price` decimal(14,4) NOT NULL,
	`unit_cost` decimal(14,4) NOT NULL DEFAULT (0),
	`discount_amount` decimal(14,2) NOT NULL DEFAULT (0),
	`tax_amount` decimal(14,2) NOT NULL DEFAULT (0),
	`subtotal` decimal(14,2) NOT NULL,
	`total_amount` decimal(14,2) NOT NULL,
	`created_at` timestamp DEFAULT (now()),
	CONSTRAINT `chk_sale_items_qty` CHECK(`sale_items`.`quantity` > 0 AND `sale_items`.`base_quantity` > 0),
	CONSTRAINT `chk_sale_items_amounts` CHECK(`sale_items`.`unit_price` >= 0 AND `sale_items`.`unit_cost` >= 0 AND `sale_items`.`subtotal` >= 0 AND `sale_items`.`total_amount` >= 0)
);

CREATE TABLE `sale_payments` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`sale_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`payment_method` enum('CASH','CARD','GCASH','MAYA','BANK_TRANSFER','OTHER') NOT NULL,
	`amount` decimal(14,2) NOT NULL,
	`reference_number` varchar(150),
	`payment_status` enum('PENDING','AUTHORIZED','PAID','FAILED','REFUNDED') NOT NULL DEFAULT 'PENDING',
	`paid_at` datetime,
	`created_at` timestamp DEFAULT (now()),
	CONSTRAINT `chk_sale_payments_amount` CHECK(`sale_payments`.`amount` > 0)
);

CREATE TABLE `sale_prescriptions` (
	`sale_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`prescription_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	CONSTRAINT PRIMARY KEY(`sale_id`,`prescription_id`)
);

CREATE TABLE `sales_return_items` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`sales_return_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`sale_item_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`inventory_batch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`quantity` decimal(14,3) NOT NULL,
	`unit_price` decimal(14,4) NOT NULL,
	`refund_amount` decimal(14,2) NOT NULL,
	`disposition` enum('RESTOCK','QUARANTINE','DAMAGED','DISPOSE') NOT NULL,
	`created_at` timestamp DEFAULT (now()),
	CONSTRAINT `chk_sales_return_items_qty` CHECK(`sales_return_items`.`quantity` > 0 AND `sales_return_items`.`unit_price` >= 0 AND `sales_return_items`.`refund_amount` >= 0)
);

CREATE TABLE `sales_returns` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`sale_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`return_number` varchar(100) NOT NULL,
	`customer_id` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`return_reason` text NOT NULL,
	`refund_amount` decimal(14,2) NOT NULL DEFAULT (0),
	`status` enum('DRAFT','PENDING_APPROVAL','APPROVED','PROCESSED','REJECTED','CANCELLED') NOT NULL DEFAULT 'DRAFT',
	`processed_by` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`approved_by` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_sales_returns_number` UNIQUE INDEX(`return_number`),
	CONSTRAINT `chk_sales_returns_amount` CHECK(`sales_returns`.`refund_amount` >= 0)
);

CREATE TABLE `sales` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`customer_id` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`cashier_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`cash_register_session_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`invoice_number` varchar(100) NOT NULL,
	`transaction_date` datetime NOT NULL,
	`subtotal` decimal(14,2) NOT NULL DEFAULT (0),
	`discount_amount` decimal(14,2) NOT NULL DEFAULT (0),
	`tax_amount` decimal(14,2) NOT NULL DEFAULT (0),
	`total_amount` decimal(14,2) NOT NULL DEFAULT (0),
	`amount_paid` decimal(14,2) NOT NULL DEFAULT (0),
	`change_amount` decimal(14,2) NOT NULL DEFAULT (0),
	`status` enum('PENDING','COMPLETED','PARTIALLY_REFUNDED','REFUNDED','VOIDED') NOT NULL DEFAULT 'PENDING',
	`idempotency_key` varchar(100),
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_sales_invoice` UNIQUE INDEX(`invoice_number`),
	CONSTRAINT `uq_sales_idempotency` UNIQUE INDEX(`idempotency_key`),
	CONSTRAINT `chk_sales_amounts` CHECK(`sales`.`subtotal` >= 0 AND `sales`.`discount_amount` >= 0 AND `sales`.`tax_amount` >= 0 AND `sales`.`total_amount` >= 0 AND `sales`.`amount_paid` >= 0 AND `sales`.`change_amount` >= 0)
);

CREATE TABLE `stock_transfer_items` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`stock_transfer_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`product_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`source_inventory_batch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`quantity_requested` decimal(14,3) NOT NULL,
	`quantity_shipped` decimal(14,3) NOT NULL DEFAULT (0),
	`quantity_received` decimal(14,3) NOT NULL DEFAULT (0),
	`destination_inventory_batch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`created_at` timestamp DEFAULT (now()),
	CONSTRAINT `chk_transfer_items_qty` CHECK(`stock_transfer_items`.`quantity_requested` > 0 AND `stock_transfer_items`.`quantity_shipped` >= 0 AND `stock_transfer_items`.`quantity_received` >= 0 AND `stock_transfer_items`.`quantity_received` <= `stock_transfer_items`.`quantity_shipped` AND `stock_transfer_items`.`quantity_shipped` <= `stock_transfer_items`.`quantity_requested`)
);

CREATE TABLE `stock_transfers` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`transfer_number` varchar(100) NOT NULL,
	`source_branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`destination_branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`status` enum('DRAFT','PENDING_APPROVAL','APPROVED','IN_TRANSIT','PARTIALLY_RECEIVED','RECEIVED','REJECTED','CANCELLED') NOT NULL DEFAULT 'DRAFT',
	`requested_by` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`approved_by` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`shipped_at` datetime,
	`received_at` datetime,
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_stock_transfers_number` UNIQUE INDEX(`transfer_number`),
	CONSTRAINT `chk_transfer_branches` CHECK(`stock_transfers`.`source_branch_id` <> `stock_transfers`.`destination_branch_id`)
);

CREATE TABLE `suppliers` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`code` varchar(50) NOT NULL,
	`name` varchar(255) NOT NULL,
	`contact_name` varchar(255),
	`phone` varchar(50),
	`email` varchar(255),
	`tax_id` varchar(100),
	`payment_terms` varchar(255),
	`address` text,
	`is_active` boolean NOT NULL DEFAULT true,
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_suppliers_code` UNIQUE INDEX(`code`)
);

CREATE TABLE `units` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`name` varchar(100) NOT NULL,
	`abbreviation` varchar(30) NOT NULL,
	CONSTRAINT `uq_units_name` UNIQUE INDEX(`name`),
	CONSTRAINT `uq_units_abbreviation` UNIQUE INDEX(`abbreviation`)
);

CREATE TABLE `user_roles` (
	`user_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`role_id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	`assigned_at` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT PRIMARY KEY(`user_id`,`role_id`)
);

CREATE TABLE `users` (
	`id` char(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
	`branch_id` char(36) CHARACTER SET ascii COLLATE ascii_bin,
	`name` varchar(255) NOT NULL,
	`email` varchar(255) NOT NULL,
	`employee_number` varchar(50),
	`password` varchar(255) NOT NULL,
	`is_active` boolean NOT NULL DEFAULT true,
	`email_verified_at` timestamp,
	`remember_token` varchar(100),
	`created_at` timestamp DEFAULT (now()),
	`updated_at` timestamp DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `uq_users_email` UNIQUE INDEX(`email`),
	CONSTRAINT `uq_users_employee_number` UNIQUE INDEX(`employee_number`)
);

