CREATE SQL SECURITY definer VIEW `v_expiring_inventory` AS (select `inventory_batches`.`id` as `batch_id`, `inventory_batches`.`branch_id`, `inventory_batches`.`product_id`, `products`.`product_name`, `inventory_batches`.`batch_number`, `inventory_batches`.`quantity_available`, `inventory_batches`.`expiration_date`, DATEDIFF(`inventory_batches`.`expiration_date`, CURRENT_DATE) as `days_remaining` from `inventory_batches` inner join `products` on `products`.`id` = `inventory_batches`.`product_id` where ((`inventory_batches`.`quantity_available` > '0') and ((`inventory_batches`.`expiration_date` is not null)) and (`inventory_batches`.`expiration_date` <= DATE_ADD(CURRENT_DATE, INTERVAL 180 DAY))));
CREATE SQL SECURITY definer VIEW `v_inventory_stock` AS (select `id` as `inventory_id`, `branch_id`, `product_id`, `quantity_on_hand`, `quantity_reserved`, `quantity_on_hand` - `quantity_reserved` as `quantity_available` from `inventories`);
